import sys

def is_unique(row):
    """Check if a row has all unique elements"""
    return len(set(row)) == 9

def solve_sudoku(grid):
    """Solve the Sudoku puzzle"""
    # Make a copy of the grid
    grid = [row[:] for row in grid]

    # Try to make each row have duplicates
    for i in range(9):
        if is_unique(grid[i]):
            # Change the last element to match the first
            grid[i][-1] = grid[i][0]

    # Try to make each column have duplicates
    for j in range(9):
        if is_unique([grid[i][j] for i in range(9)]):
            # Change the last element to match the first
            for i in range(8, -1, -1):
                if grid[i][j] != grid[0][j]:
                    grid[i][j] = grid[0][j]
                    break

    # Try to make each 3x3 block have duplicates
    for block_row in range(3):
        for block_col in range(3):
            # Extract the block
            block = []
            for i in range(3 * block_row, 3 * block_row + 3):
                for j in range(3 * block_col, 3 * block_col + 3):
                    block.append(grid[i][j])

            if is_unique(block):
                # Change the last element to match the first
                for i in range(3 * block_row, 3 * block_row + 3):
                    for j in range(3 * block_col, 3 * block_col + 3):
                        if grid[i][j] != block[0]:
                            grid[i][j] = block[0]
                            break
                    else:
                        continue
                    break

    return grid

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    t = int(data[0])
    idx = 1

    for _ in range(t):
        grid = []
        for _ in range(9):
            grid.append(data[idx:idx+9])
            idx += 9

        solved = solve_sudoku(grid)
        for row in solved:
            print(''.join(row))

if __name__ == "__main__":
    main()
