def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # dp[x] = length of longest consecutive subsequence ending with integer x
    dp = {}
    max_len = 0
    max_val = None

    for i, num in enumerate(a, 1):
        # Check if we can extend a subsequence ending at num-1
        if num - 1 in dp:
            current_len = dp[num - 1] + 1
        else:
            current_len = 1

        # Update dp
        if num in dp:
            if current_len > dp[num]:
                dp[num] = current_len
        else:
            dp[num] = current_len

        # Track maximum
        if current_len > max_len or (current_len == max_len and num < max_val):
            max_len = current_len
            max_val = num

    # Reconstruct the subsequence
    result = []
    current_val = max_val

    # Find the last occurrence of max_val
    for i, num in enumerate(a, 1):
        if num == max_val:
            result.append(i)
            current_val -= 1
            while current_val in dp and dp[current_val] >= max_len - (len(result) - 1):
                # Find the last occurrence of current_val that can be part of the subsequence
                for j in range(i - 1, 0, -1):
                    if a[j - 1] == current_val:
                        result.append(j)
                        current_val -= 1
                        break

    print(max_len)
    print(' '.join(map(str, result)))

