import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        m = int(next(it))

        # Count boxes of each power of two
        box_count = [0] * 61  # 0 to 60
        for _ in range(m):
            a = int(next(it))
            # Find the power of two
            power = a.bit_length() - 1
            box_count[power] += 1

        # Check if we can cover all bits of n
        total_bits = 0
        for i in range(61):
            if (n >> i) & 1:
                total_bits += 1

        # Check if we have enough boxes
        if sum(box_count) < total_bits:
            print(-1)
            continue

        # Try to cover bits from lowest to highest
        divisions = 0
        for i in range(61):
            if (n >> i) & 1:
                # We need a box of size 2^i
                if box_count[i] > 0:
                    box_count[i] -= 1
                else:
                    # Need to divide a larger box
                    found = False
                    for j in range(i + 1, 61):
                        if box_count[j] > 0:
                            # Divide from j down to i
                            divisions += (j - i)
                            # Update counts: remove one box of size 2^j
                            box_count[j] -= 1
                            # Add two boxes of size 2^(j-1)
                            box_count[j - 1] += 2
                            found = True
                            break
                    if not found:
                        print(-1)
                        break
        else:
            print(divisions)

if __name__ == "__main__":
    solve()
