        i = 1
        while i < n:
            if s[i-1] == 'M' and s[i] == 'F':
                # There's a swap needed between i-1 and i
                # We need to track this position
                moves.append(i)
                i += 1  # Skip the next position since it's been processed
            else:
                i += 1

        if not moves:
            break

        # Perform swaps from back to front to avoid interference
        for i in reversed(moves):
            s[i-1], s[i] = 'F', 'M'

        print(s)

