def solve():
    n, k = map(int, input().split())
    questions = set(map(int, input().split()))

    # Count valid (start, end) pairs
    count = 0

    # For each possible (start, end) pair
    for start in range(1, n + 1):
        for end in range(1, n + 1):
            # Check if (start, end) is valid
            # Case 1: start == end, never move
            if start == end and start not in questions:
                count += 1
            # Case 2: start != end, move once
            elif start != end:
                # She must move exactly once from start to either start+1 or start-1
                if start + 1 <= n:
                    if start + 1 == end and start + 1 not in questions:
                        # She moves from start to start+1 at some point
                        # Before the move, she is at start and never on questions
                        # After the move, she is at start+1 and never on questions
                        # Also, start must not be in questions
