import sys

def compute_f(arr):
    """Compute f for an array."""
    if len(arr) == 1:
        return arr[0]
    new_arr = [arr[i] ^ arr[i + 1] for i in range(len(arr) - 1)]
    return compute_f(new_arr)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:n + 1]))
    q = int(data[n + 1])
    queries = []
    idx = n + 2

    for _ in range(q):
        l = int(data[idx])
        r = int(data[idx + 1])
        queries.append((l - 1, r - 1))  # convert to 0-indexed
        idx += 2

    results = []
    for l, r in queries:
        max_val = 0
        # Try all subsegments [i, j] where l <= i <= j <= r
        for i in range(l, r + 1):
            for j in range(i, r + 1):
                subseg = a[i:j + 1]
                val = compute_f(subseg)
                if val > max_val:
                    max_val = val
        results.append(str(max_val))

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
