    """Check if n can be expressed as sum of two triangular numbers."""
    max_a = int((2 * n) ** 0.5) + 1
    for a in range(max_a):
        t_a = a * (a + 1) // 2
        remaining = n - t_a
        if remaining < 0:
            continue
        if is_triangular(remaining):
            return True
    return False

