import sys
from collections import deque

def solve():
    n = int(sys.stdin.readline())

    # Containers: stack, queue, deck front
    stack = []
    queue = deque()
    deck_front = deque()

    for _ in range(n):
        cmd = int(sys.stdin.readline())

        if cmd == 0:
            # Extract operation
            # Extract from containers in the order: stack, queue, deck front
            extracted = []

            # Check if stack is non-empty
            if stack:
                extracted.append(stack.pop())
            # Check if queue is non-empty
            if queue:
                extracted.append(queue.popleft())
            # Check if deck front is non-empty
            if deck_front:
                extracted.append(deck_front.popleft())

            k = len(extracted)
            print(k, end=' ')
