def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    k = int(data[2])

    grid = []
    idx = 3
    for i in range(n):
        row = []
        for j in range(m):
            row.append(data[idx])
            idx += 1
        grid.append(row)

    # Find all empty cells
    empty_cells = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                empty_cells.append((i, j))

    # BFS to find spanning tree
    visited = [[False] * m for _ in range(n)]
    q = deque()
    start = empty_cells[0]
    q.append(start)
    visited[start[0]][start[1]] = True

    traversal_order = [start]

    while q:
        x, y = q.popleft()
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m:
                if not visited[nx][ny] and grid[nx][ny] == '.':
                    visited[nx][ny] = True
                    q.append((nx, ny))
                    traversal_order.append((nx, ny))

    # Turn last k cells into walls
    for i in range(len(traversal_order) - 1, len(traversal_order) - 1 - k, -1):
        x, y = traversal_order[i]
        grid[x][y] = 'X'

    # Print result
    for row in grid:
        print(''.join(row))

if __name__ == '__main__':
    solve()
