def rotate_direction(dx, dy):
    """Rotate direction by 45 degrees counterclockwise."""
    # Use the pattern of direction vectors
    # Upward (0, 1) → Top-left (-1, 1), Top-right (1, 1)
    # Top-left (-1, 1) → Left (-1, 0), Bottom-left (-1, -1)
    # Left (-1, 0) → Bottom-left (-1, -1), Downward (0, -1)
    # Bottom-left (-1, -1) → Downward (0, -1), Bottom-right (1, -1)
    # Downward (0, -1) → Bottom-right (1, -1), Right (1, 0)
    # Bottom-right (1, -1) → Right (1, 0), Top-right (1, 1)
    # Right (1, 0) → Top-right (1, 1), Upward (0, 1)
    # Top-right (1, 1) → Upward (0, 1), Top-left (-1, 1)

    if dx == 0 and dy == 1:
        return (-1, 1), (1, 1)
    elif dx == -1 and dy == 1:
        return (-1, 0), (-1, -1)
    elif dx == -1 and dy == 0:
        return (-1, -1), (0, -1)
    elif dx == -1 and dy == -1:
        return (0, -1), (1, -1)
    elif dx == 0 and dy == -1:
        return (1, -1), (1, 0)
    elif dx == 1 and dy == -1:
        return (1, 0), (0, 1)
    elif dx == 1 and dy == 0:
        return (0, 1), (-1, 1)
    elif dx == 1 and dy == 1:
        return (0, 1), (-1, 1)

