directions = [(0, 1)]

for i in range(n):
    new_directions = []
    for dx, dy in directions:
        # Move ti cells
        for _ in range(t[i]):
            visited.add(position)
            position = (position[0] + dx, position[1] + dy)

        # If not last level, explode and create new directions
        if i < n - 1:
            new_dir1, new_dir2 = rotate_direction(dx, dy)
            new_directions.append(new_dir1)
            new_directions.append(new_dir2)

    # Update directions for next level
    directions = new_directions

print(len(visited))
