    """Check if x is a triangular number with b ≥ 1"""
    if x == 0:
        return False
    discriminant = 1 + 8 * x
    sqrt_discriminant = math.isqrt(discriminant)
    return sqrt_discriminant * sqrt_discriminant == discriminant

def solve():
    n = int(input())

    # Check if n can be expressed as sum of two triangular numbers
    for a in range(1, int(math.isqrt(2 * n)) + 1):
        triangular_a = a * (a + 1) // 2
        remaining = n - triangular_a

        if remaining < 0:
            continue

        if is_triangular(remaining):
            print("YES")
            return

    print("NO")

solve()
