    k = float(parts[2])

    # Read old skills
    old_skills = {}
    for i in range(1, 1 + n):
        skill_data = data[i].split()
        name = skill_data[0]
        exp = int(skill_data[1])
        old_skills[name] = exp

    # Read new class skills
    new_class_skills = set()
    for i in range(1 + n, 1 + n + m):
