    # Process transmigration
    result = {}

    # Process old skills
    for name, exp in old_skills.items():
        new_exp = int(k * exp)
        if new_exp >= 100:
            result[name] = new_exp

    # Add new class skills
    for name in new_class_skills:
        if name not in result:
            result[name] = 0

    # Sort lexicographically
    sorted_skills = sorted(result.items())

    # Output
    print(len(sorted_skills))
    for name, exp in sorted_skills:
