import sys

def solve():
    n = int(sys.stdin.readline())

    if n % 2 == 0:
        print("NO")
        return

    print("YES")

    # Construct the sequence
    low = []
    high = []
    for i in range(1, n + 1):
        low.append(i)
    for i in range(n + 1, 2 * n + 1):
        high.append(i)

    # Pattern: low, high, high, low, low, high...
    result = []
    i = 0
    while len(result) < 2 * n:
        # low, high, high, low, low, high...
        if i % 3 == 0:
            result.append(low[i // 3])
        elif i % 3 == 1 or i % 3 == 2:
            result.append(high[i // 3])
        i += 1

    print(' '.join(map(str, result)))

if __name__ == "__main__":
    solve()
