import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    heights = list(map(int, data[1:1+n]))

    max_height = max(heights)

    strokes = 0

    for h in range(1, max_height + 1):
        # Count contiguous segments at height h
        count = 0
        i = 0
        while i < n:
            if heights[i] >= h:
                count += 1
                # Move past this contiguous segment
                while i < n and heights[i] >= h:
                    i += 1
            else:
                i += 1

        strokes += count

    print(strokes)

if __name__ == "__main__":
    solve()
