    """Compute the function f for a given subsegment."""
    while len(subsegment) > 1:
        new_segment = []
        for i in range(len(subsegment) - 1):
            new_segment.append(subsegment[i] ^ subsegment[i + 1])
        subsegment = new_segment
    return subsegment[0]

