def solve():
    s = sys.stdin.readline().strip()
    k = int(sys.stdin.readline().strip())
    forbidden = set()

    for _ in range(k):
        pair = sys.stdin.readline().strip()
        forbidden.add((pair[0], pair[1]))
        forbidden.add((pair[1], pair[0]))

    # dp[i][c] = minimum removals to process first i characters with last character c
    # We'll use a dictionary of dictionaries for efficiency
    dp = {chr(ord('a') + i): float('inf') for i in range(26)}

    # Initialize: process 0 characters, no last character
    for c in dp:
        dp[c] = float('inf')

    # We can also consider the empty string as a base case
    dp[''] = 0

    for char in s:
        new_dp = {chr(ord('a') + i): float('inf') for i in range(26)}

        # Option 1: Remove the current character
        for c in dp:
            new_dp[c] = min(new_dp[c], dp[c])

        # Option 2: Keep the current character
        for prev_char in dp:
            if prev_char == '':
                # No previous character, just keep the current character
                new_dp[char] = min(new_dp[char], dp[prev_char])
            else:
                # Check if prev_char and char form a forbidden pair
                if (prev_char, char) in forbidden:
                    # Need to remove prev_char, so add 1 to removal count
                    new_dp[char] = min(new_dp[char], dp[prev_char] + 1)
                else:
                    # Just keep both characters
                    new_dp[char] = min(new_dp[char], dp[prev_char])

        dp = new_dp

    # The answer is the minimum removal count among all possible last characters
    print(min(dp.values()))

if __name__ == "__main__":
    solve()
