    empty_cells = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                empty_cells.append((i, j))

    # BFS to find spanning tree
    from collections import deque

    # Pick an arbitrary starting point
    start = empty_cells[0]
    visited = set()
    visited.add(start)
    parent = {}

    q = deque([start])
    while q:
        x, y = q.popleft()
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == '.' and (nx, ny) not in visited:
                visited.add((nx, ny))
                parent[(nx, ny)] = (x, y)
                q.append((nx, ny))

    # Find cells to remove
    remove_cells = set()
