def solve():
    s = input().strip()
    k = int(input())
    forbidden = set()

    # Read forbidden pairs
    for _ in range(k):
        pair = input().strip()
        forbidden.add((pair[0], pair[1]))
        forbidden.add((pair[1], pair[0]))

    n = len(s)
    # dp[i][last] = minimum removals to process first i letters, ending with letter 'last'
    # We use a dictionary of dictionaries for efficiency
    dp = [{} for _ in range(n + 1)]
    dp[0][None] = 0  # No letters processed, no last letter

    for i in range(n):
        curr = s[i]
        for last, removals in dp[i].items():
            # Option 1: remove the current letter
            if curr in dp[i+1]:
                dp[i+1][curr] = min(dp[i+1][curr], removals)
            else:
                dp[i+1][curr] = removals

            # Option 2: keep the current letter
            if last is None:
                # No previous letter, just add it
                if curr in dp[i+1]:
                    dp[i+1][curr] = min(dp[i+1][curr], removals + 1)
                else:
                    dp[i+1][curr] = removals + 1
            else:
                # Check if curr and last form a forbidden pair
                if (last, curr) not in forbidden:
                    if curr in dp[i+1]:
                        dp[i+1][curr] = min(dp[i+1][curr], removals + 1)
                    else:
                        dp[i+1][curr] = removals + 1

    # Find the minimum removals among all possible endings
    min_removals = min(dp[n].values())
    print(min_removals)

solve()
