def count_ones(x):
    """Count the number of '1' bits in the binary representation of x."""
    return bin(x).count('1')

def solve_query(l, r):
    """Find the number x in [l, r] with the most '1' bits, smallest in case of tie."""
    # Find the smallest power of 2 greater than r
    power = 1
    while power <= r:
        power *= 2

    # The number with all bits set to 1 that is less than power
    all_ones = power - 1

    # If all_ones is in the range [l, r], return it
    if l <= all_ones <= r:
        return all_ones

    # Otherwise, find the number with the most '1' bits that is >= l and < all_ones
    # This would be a number with one fewer bit set
    # Find the largest number with one fewer bit set that is >= l

    # The largest number with one fewer bit set is all_ones >> 1
    # But we need to check if this is >= l
    candidate = all_ones >> 1

    # If the candidate is still less than l, we need to find the smallest number >= l
    # with the most '1' bits
    if candidate < l:
        # Try numbers from l to min(r, all_ones - 1)
        best = l
        for x in range(l, min(r, all_ones) + 1):
            if count_ones(x) > count_ones(best):
                best = x
        return best

    return candidate

def main():
    n = int(input())
    for _ in range(n):
        l, r = map(int, input().split())
        print(solve_query(l, r))

if __name__ == "__main__":
    main()
"}

