import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    times = list(map(int, data[1:1+n]))

    # dp[i] = minimum cost to cover first i trips
    dp = [0] * (n + 1)

    for i in range(1, n + 1):
        ti = times[i-1]

        # One-trip ticket
        dp[i] = dp[i-1] + 20

        # 90-minute ticket
        # Find the latest trip j such that times[j] >= ti - 89
        left, right = 0, i - 1
        while left <= right:
            mid = (left + right) // 2
            if times[mid] >= ti - 89:
                right = mid - 1
            else:
                left = mid + 1
        j = left - 1
        if j >= 0:
            dp[i] = min(dp[i], dp[j] + 50)

        # 1-day ticket
        # Find the latest trip j such that times[j] >= ti - 1439
        left, right = 0, i - 1
        while left <= right:
            mid = (left + right) // 2
            if times[mid] >= ti - 1439:
                right = mid - 1
            else:
                left = mid + 1
        j = left - 1
        if j >= 0:
            dp[i] = min(dp[i], dp[j] + 120)

        # Charge is dp[i] - dp[i-1]
        print(dp[i] - dp[i-1])

if __name__ == "__main__":
    solve()
