def update_probabilities(c, m, p, item, v):
    """Update probabilities after drawing an item."""
    if item == 'c':
        a = c
        new_c = 0.0

        # Distribute reduced probability equally among remaining items
        if m > 0:
            m += a / 2
        if p > 0:
            p += a / 2
    elif item == 'm':
        a = m
        new_m = 0.0

        if c > 0:
            c += a / 2
        if p > 0:
            p += a / 2
    elif item == 'p':
        # Pink Slip, quest over
        return None, None, None

    return c, m, p

def expected_races(c, m, p, v, memo):
    """Calculate expected number of races using memoization."""
    if (c, m, p) in memo:
        return memo[(c, m, p)]

    # Base case: if we already have a Pink Slip, expected races = 0
    if c <= 0 or m <= 0 or p <= 0:
        return 0.0

    # Probability of drawing each item
    prob_c = c / (c + m + p)
    prob_m = m / (c + m + p)
    prob_p = p / (c + m + p)

    # Expected value from this state
    expected = 1.0  # At least one race

    # Draw Cash
    if c > 0:
        new_c, new_m, new_p = update_probabilities(c, m, p, 'c', v)
        if new_c is not None:
            expected += prob_c * expected_races(new_c, new_m, new_p, v, memo)

    # Draw Impound Strike
    if m > 0:
        new_c, new_m, new_p = update_probabilities(c, m, p, 'm', v)
        if new_m is not None:
            expected += prob_m * expected_races(new_c, new_m, new_p, v, memo)

    # Draw Pink Slip
    if p > 0:
        expected += prob_p * expected_races(0.0, 0.0, 0.0, v, memo)

    memo[(c, m, p)] = expected
    return expected

