def count_ones(x):
    """Count the number of '1' bits in x."""
    return bin(x).count('1')

def solve_query(l, r):
    """Find the number x in [l, r] with the most '1' bits, smallest in case of tie."""
    if l == r:
        return l

    # Try all numbers of the form 2^k - 1
    # These are numbers like 1, 3, 7, 15, 31, etc.
    # They have all bits set to 1 up to position k-1

    # Check from the largest possible down
    k = r.bit_length()
    while k >= 1:
        candidate = (1 << k) - 1
        if candidate >= l and candidate <= r:
            # Check if this is the best answer
            # If it has the same number of '1' bits as r, we need the smallest
            best = candidate
            k -= 1
            continue
        k -= 1

    # If we didn't find any, just return l or r based on which has more '1' bits
    if count_ones(l) > count_ones(r):
        return l
    elif count_ones(r) > count_ones(l):
        return r
    else:
        return l

n = int(input())
for _ in range(n):
    l, r = map(int, input().split())
    print(solve_query(l, r))
