import sys

# Correct recursive computation of f
def compute_f(arr):
    if len(arr) == 1:
        return arr[0]

    # Compute XOR of adjacent pairs
    next_arr = [arr[i] ^ arr[i + 1] for i in range(len(arr) - 1)]

    # Recursively compute f on the new array
    return compute_f(next_arr)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    a = [int(next(it)) for _ in range(n)]
    q = int(next(it))
    queries = []

    for _ in range(q):
        l = int(next(it))
        r = int(next(it))
        queries.append((l, r))

    max_result = 0

    for l, r in queries:
        # Consider all subsegments within [l, r]
        for i in range(l, r + 1):
            for j in range(i, r + 1):
                # Subsegment a[i..j]
                subarr = a[i - 1:j]  # Python slice is start inclusive, end exclusive
                val = compute_f(subarr)
                max_result = max(max_result, val)

    print(max_result)

if __name__ == "__main__":
    solve()
