def solve():
    s = input().strip()
    k = int(input())
    forbidden = set()
    for _ in range(k):
        pair = input().strip()
        a, b = pair[0], pair[1]
        forbidden.add((a, b))
        forbidden.add((b, a))

    n = len(s)

    # dp[i][last_char] = min deletions to process first i chars, ending with last_char
    # We use a dictionary for last_char to save space
    dp = {None: 0}

    for i in range(n):
        new_dp = {}
        char = s[i]

        # Option 1: delete current character
        for last_char, deletions in dp.items():
            if last_char in new_dp:
                new_dp[last_char] = min(new_dp[last_char], deletions)
            else:
                new_dp[last_char] = deletions

        # Option 2: keep current character
        for last_char, deletions in dp.items():
            if (last_char, char) in forbidden:
                # Forbidden pair, need to delete last_char
                if char in new_dp:
                    new_dp[char] = min(new_dp[char], deletions + 1)
                else:
                    new_dp[char] = deletions + 1
            else:
                # Not forbidden, keep both characters
                if char in new_dp:
                    new_dp[char] = min(new_dp[char], deletions)
                else:
                    new_dp[char] = deletions

        dp = new_dp

    print(min(dp.values()))

