def is_triangular(x):
    """Check if x is a triangular number."""
    # Solve k(k+1)/2 = x
    # k^2 + k - 2x = 0
    # k = (-1 + sqrt(1 + 8x)) / 2
    discriminant = 1 + 8 * x
    sqrt_discriminant = int(discriminant ** 0.5)

    # Check if discriminant is a perfect square and if k is an integer
    if sqrt_discriminant * sqrt_discriminant != discriminant:
        return False

    k = (-1 + sqrt_discriminant) // 2
    return k * (k + 1) // 2 == x

def can_be_sum_of_two_triangular_numbers(n):
    """Check if n can be expressed as the sum of two triangular numbers."""
    # Iterate over possible values of a
    for a in range(1, int((2 * n) ** 0.5) + 1):
        triangular_a = a * (a + 1) // 2
        remaining = n - triangular_a

        if remaining < 0:
            continue

        if is_triangular(remaining):
            return True

    return False

n = int(input())
