def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Sort the sequence while keeping track of original indices
    sorted_with_indices = sorted((val, idx) for idx, val in enumerate(a, 1))

    # Traverse the sorted sequence and group elements
    groups = []
    current_group = []

    for val, orig_idx in sorted_with_indices:
        if not current_group:
            # Start a new subsequence
            current_group.append(orig_idx)
        else:
            # Check if this element should go into the current subsequence
            # We look at the original positions of elements in the current subsequence
            # If the current element's original position is less than all original positions in the current subsequence,
            # it means it should come before them in the sorted sequence and needs to be in the same subsequence
            should_go_together = False
            for idx in current_group:
                if orig_idx < idx:
                    should_go_together = True
                    break

            if should_go_together:
                current_group.append(orig_idx)
            else:
                # Start a new subsequence
                groups.append(current_group)
                current_group = [orig_idx]

    if current_group:
        groups.append(current_group)

    # Output the result
    print(len(groups))
    for group in groups:
        print(len(group), end=' ')
        print(' '.join(map(str, group)))

