import sys

def solve():
    data = sys.stdin.read().split()
    idx = 0
    n = int(data[idx])
    idx += 1

    edges = []
    tree = [[] for _ in range(n + 1)]
    for i in range(n - 1):
        u = int(data[idx])
        v = int(data[idx + 1])
        idx += 2
        edges.append((u, v))
        tree[u].append((v, i))
        tree[v].append((u, i))

    k = int(data[idx])
    idx += 1

    # Preprocess parent arrays for LCA
    parent = [[-1] * (n + 1) for _ in range(20)]  # 2^20 is more than enough
    depth = [0] * (n + 1)

    def dfs(u, p):
        parent[0][u] = p
        for v, _ in tree[u]:
            if v != p:
                depth[v] = depth[u] + 1
                dfs(v, u)

    dfs(1, -1)

    # Binary lifting for LCA
    for j in range(1, 20):
        for i in range(1, n + 1):
            if parent[j-1][i] != -1:
                parent[j][i] = parent[j-1][parent[j-1][i]]

    def lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        # Bring u to the same depth as v
        for j in range(19, -1, -1):
            if depth[u] - (1 << j) >= depth[v]:
                u = parent[j][u]
        if u == v:
            return u
        for j in range(19, -1, -1):
            if parent[j][u] != -1 and parent[j][u] != parent[j][v]:
                u = parent[j][u]
                v = parent[j][v]
        return parent[0][u]

    # Count edge usage
    edge_count = [0] * (n - 1)

    for _ in range(k):
        a = int(data[idx])
        b = int(data[idx + 1])
        idx += 2
        l = lca(a, b)

        # Traverse from a to l
        curr = a
        while curr != l:
            for neighbor, edge_idx in tree[curr]:
                if neighbor == parent[0][curr]:
                    edge_count[edge_idx] += 1
                    curr = neighbor
                    break

        # Traverse from b to l
        curr = b
        while curr != l:
            for neighbor, edge_idx in tree[curr]:
                if neighbor == parent[0][curr]:
                    edge_count[edge_idx] += 1
                    curr = neighbor
                    break

    print(' '.join(map(str, edge_count)))

