import sys

def solve_rebus(equation):
    # Parse the equation
    parts = equation.split()
    n = int(parts[-1])
    ops = parts[1:-1]
    num_questions = len(ops) + 1

    # Try to set most question marks to 1 and adjust one or two
    for first_val in range(1, n + 1):
        # Set first question mark to first_val
        # Set all other question marks to 1
        values = [first_val] + [1] * (num_questions - 1)

        # Calculate the result
        result = values[0]
        for i in range(1, num_questions):
            if ops[i-1] == '+':
                result += values[i]
            else:
                result -= values[i]

        if result == n:
            return values

    # If not found, try adjusting one question mark
    for i in range(num_questions):
        for val in range(1, n + 1):
            # Set question mark i to val, others to 1
            values = [1] * num_questions
            values[i] = val

            # Calculate the result
            result = values[0]
            for j in range(1, num_questions):
                if ops[j-1] == '+':
                    result += values[j]
                else:
                    result -= values[j]

            if result == n:
                return values

    # If not found, try adjusting two question marks
    for i in range(num_questions):
        for j in range(i + 1, num_questions):
            for val_i in range(1, n + 1):
                for val_j in range(1, n + 1):
                    # Set question marks i and j to val_i and val_j, others to 1
                    values = [1] * num_questions
                    values[i] = val_i
                    values[j] = val_j

                    # Calculate the result
                    result = values[0]
                    for k in range(1, num_questions):
                        if ops[k-1] == '+':
                            result += values[k]
                        else:
                            result -= values[k]

                    if result == n:
                        return values

    return None

def main():
    equation = sys.stdin.read().strip()
    parts = equation.split()
    n = int(parts[-1])
    ops = parts[1:-1]
    num_questions = len(ops) + 1

    # Try to find a solution
    solution = solve_rebus(equation)

    if solution:
        print("Possible")
        output = f"{solution[0]}""
        for i in range(1, num_questions):
            output += f" {ops[i-1]} {solution[i]}"
        output += f" = {n}"
        print(output)
    else:
        print("Impossible")

if __name__ == "__main__":
    main()
