import sys

def solve():
    s = sys.stdin.readline().strip()
    k = int(sys.stdin.readline())
    forbidden = set()
    for _ in range(k):
        pair = sys.stdin.readline().strip()
        forbidden.add((pair[0], pair[1]))
        forbidden.add((pair[1], pair[0]))

    # DP: dp[i][c] = min removals to process first i chars, ending with char c
    # We'll use a dictionary of dictionaries
    dp = {chr(ord('a') + i): float('inf') for i in range(26)}
    dp[s[0]] = 0  # Start with the first character

    for i in range(1, len(s)):
        curr_char = s[i]
        new_dp = {chr(ord('a') + i): float('inf') for i in range(26)}

        # Option 1: Remove the current character
        for prev_char, val in dp.items():
            new_dp[prev_char] = min(new_dp[prev_char], val)

        # Option 2: Keep the current character
        for prev_char, val in dp.items():
            if (prev_char, curr_char) not in forbidden:
                new_dp[curr_char] = min(new_dp[curr_char], val + 1)

        dp = new_dp

    # The answer is the minimum value in dp
    print(min(dp.values()))

if __name__ == "__main__":
    solve()

