import math

def distance(p1, p2):
    """Calculate the Euclidean distance between two points."""
    return math.sqrt((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2)

def solve():
    # Read input
    n, px, py = map(int, input().split())
    polygon = []
    for _ in range(n):
        x, y = map(int, input().split())
        polygon.append((x, y))

    # Find the closest and farthest points from P
    min_dist = float('inf')
    max_dist = 0

    for (x, y) in polygon:
        dist = distance((x, y), (px, py))
        if dist < min_dist:
            min_dist = dist
        if dist > max_dist:
            max_dist = dist

    # Calculate the area of the cleared region
    area = math.pi * (max_dist**2 - min_dist**2)

    # Print with sufficient precision
    print(area)

if __name__ == "__main__":
    solve()
