import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    comparisons = data[1] if len(data) > 1 else ""

    toffees = [1] * n

    # Left to right
    for i in range(n - 1):
        if comparisons[i] == 'R':  # right > left
            toffees[i + 1] = max(toffees[i + 1], toffees[i] + 1)
        elif comparisons[i] == '=':
            toffees[i + 1] = max(toffees[i + 1], toffees[i])

    # Right to left
    for i in range(n - 1, 0, -1):
        if comparisons[i - 1] == 'L':  # left > right
            toffees[i - 1] = max(toffees[i - 1], toffees[i] + 1)
        elif comparisons[i - 1] == '=':
            toffees[i - 1] = max(toffees[i - 1], toffees[i])

    print(' '.join(map(str, toffees)))

if __name__ == "__main__":
    solve()
"}

