import sys

def solve(s):
    # Find all positions of "AB"
    ab_positions = []
    for i in range(len(s) - 1):
        if s[i] == 'A' and s[i+1] == 'B':
            ab_positions.append(i)

    # Find all positions of "BA"
    ba_positions = []
    for i in range(len(s) - 1):
        if s[i] == 'B' and s[i+1] == 'A':
            ba_positions.append(i)

    # Check if there's a non-overlapping pair
    for ab in ab_positions:
        for ba in ba_positions:
            # Check if they don't overlap
            if ab + 1 < ba or ba + 1 < ab:
                return "YES"

    return "NO"

def main():
    s = sys.stdin.readline().strip()
    print(solve(s))

if __name__ == "__main__":
    main()
